def comps(cells):
    cells=set(cells); seen=set(); out=[]
    for c in cells:
        if c in seen: continue
        st=[c]; comp=set()
        while st:
            p=st.pop()
            if p in seen or p not in cells: continue
            seen.add(p); comp.add(p)
            r,cc=p
            st+= [(r+dr,cc+dc) for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))]
        out.append(comp)
    return out

def norm(cells):
    rs=[r for r,_ in cells]; cs=[c for _,c in cells]
    r0,c0=min(rs),min(cs)
    h=max(rs)-r0+1; w=max(cs)-c0+1
    g=[[1 if (r0+i,c0+j) in cells else 0 for j in range(w)] for i in range(h)]
    return tuple(tuple(row) for row in g)

def rots(g):
    outs=[g]
    for _ in range(3):
        g=[list(r) for r in zip(*g[::-1])]
        outs.append(tuple(tuple(r) for r in g))
    return set(outs)

def solve(inp):
    H=len(inp); W=len(inp[0])
    sep=[j for j in range(W) if all(inp[i][j]==0 for i in range(H))]
    cut=min(sep)
    left=[row[:cut] for row in inp]; right=[row[cut:] for row in inp]
    holes=[]
    for comp in comps([(i,j) for i in range(H) for j in range(cut) if inp[i][j]==0]):
        if any(i==0 or i==H-1 or j==0 or j==cut-1 for i,j in comp): continue
        holes.append(comp)
    shapes={}
    for comp in comps([(i,j) for i in range(H) for j in range(len(right[0])) if right[i][j]!=0]):
        col=right[[p[0] for p in comp][0]][[p[1] for p in comp][0]]
        shapes[norm(comp)]=col
    out=[row[:] for row in left]
    for h in holes:
        n=norm(h)
        c=shapes.get(n)
        if c is None:
            for s,col in shapes.items():
                if n in rots([list(r) for r in s]): c=col; break
        for i,j in h: out[i][j]=c
    return out

